/// <summary>
/// N.Freidenberger  15.05.2025
/// </summary>
public void init()
{
    next init();

    FormRun   formRun = this;
    boolean   isExtended = false;

    if(formRun.args().menuItemName() == menuItemDisplayStr(AVAEcoResProductDetailsHKExtended))
    {
        isExtended = true;   
        FormDataSource    inventTableDS = formRun.dataSource(formDataSourceStr(EcoResProductDetailsExtended,InventTable));
        inventTableDS.query().dataSourceTable(tablenum(InventTable)).clearDynalinks();
    }

    FormRealControl         showHK2CurrentCtl   = formRun.design().controlName(formControlStr(EcoResProductDetailsExtended,AVAInvent_NDX_showHK2current));
    FormRealControl         showHK1CurrentCtl   = formRun.design().controlName(formControlStr(EcoResProductDetailsExtended,AVAInvent_NDX_showHK1current));
    FormRealControl         showPriceCurrentCtl = formRun.design().controlName(formControlStr(EcoResProductDetailsExtended,AVAInvent_NDX_showHK2PriceDisc));
  //  FormCheckBoxControl     showHKExtendedCtl   = formRun.design().controlName(formControlStr(EcoResProductDetailsExtended, AVAshowHKExtended));
    FormStringControl       itemIdCtr = formRun.design().controlName(formControlStr(EcoResProductDetailsExtended,InventTable_ItemIdGrid));
    itemIdCtr.isFrozen(true);

  //  showHKExtendedCtl.value(0);
    showHK2CurrentCtl.visible(isExtended);
    showHK1CurrentCtl.visible(isExtended);
    showPriceCurrentCtl.visible(isExtended);

}
